lijk feest mensen met verschillende verwachtingen bijeenbrengt en hoe samenwerking ruimte kan maken voor een andere kijk op elkaar.","work_id":987147035,"evidence":[{"note":"Retain Work5986 The Gingerbread Bakery / Laurie Gilmore; exact Dutch De Gingerbread Bakkerij ISBN 9789402717914 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-030.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p446512893"],"reference":"work:5986","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-030.json","sources":["https://openlibrary.org/works/OL42395220W","https://data.bibliotheken.nl/id/nbt/p446512893"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789402717914","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15126519,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:36.995Z","editionKey":"/books/OL60291857M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL42395220W","reviewed_at":"2026-11-03T09:35:36.993+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-048","review_status":"