a70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:36.995Z","editionKey":"/books/OL47017106M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"cover_url":null,"edition_id":987247037,"bound_title":"De vergetenen","reviewed_at":"2026-11-03T09:35:36.993+00:00","bound_isbn13":"9789022541036","evidence_url":"https://data.bibliotheken.nl/id/nbt/p27687093X","review_batch":"nl-scale-20261102-048","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987304023},"before_row":null},{"key":{"work_id":987147040,"language":"nl"},"seq":17,"relation":"catalog_work_descriptions","after_row":{"text":"Scheepsarcheoloog Haven Ambrose komt naar Positano om wrakken langs de Amalfikust te onderzoeken. Zij heeft ook een persoonlijk doel: de edelstenen terugvinden die haar vader tijdens zijn laatste duik heeft gezien. Terwijl vreemde stromingen en tegenslagen het dorp treffen, ontdekt zij een veel oudere geschiedenis over een vrouw die de zee met magie wilde beheersen. Haven probeert vast te stellen of die verhalen iets met de huidige gebeurtenissen te maken hebben. Haar zoektocht naar een schat wordt daarmee ook een onderzoek naar het geheugen van de kust.","work_id":987147040,"evidence":[{"note":"Retain Work6030 The Amalfi Curse / Sarah Penner; exact Dutch De schat van Amalfi ISBN 9789402717822 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-030.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p446512818"],"reference":"work:6030","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_sourc