jk onzichtbaar blijft.","work_id":987147037,"evidence":[{"note":"Retain Work6000 Sacred and Profane / Faye Kellerman; exact Dutch Een onreine dood ISBN 9789022531242 Hardcover. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-033.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p238776484"],"reference":"work:6000","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-033.json","sources":["https://openlibrary.org/works/OL462935W","https://data.bibliotheken.nl/id/nbt/p238776484"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789022531242","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15103158,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:36.998Z","editionKey":"/books/OL59556299M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL462935W","reviewed_at":"2026-11-03T09:35:36.993+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch":"nl-scale-20261102-048","review_status":"approved","bound_author_id":987304023},"before_row":null},{"key":{"edition_id":987247038},"seq":70,"relation":"catalog_editi