et ze Adams jongere broer Jessiah opnieuw. De vijandschap tussen hun families zou ook hun verhouding moeten bepalen. Hun gevoelens maken de zoektocht naar de waarheid echter ingewikkelder dan een helder conflict tussen twee kanten.","work_id":987147058,"evidence":[{"note":"Retain Work6288 Heavy & Light / Lena Kiefer; exact Dutch Zwaar en licht ISBN 9789021488806 Paperback. KB exact-title, author and original-title references compared with the existing source-edition parent. Reuse original content review content-review-034.json. No new Work, changed first-publication year, merged author, additional Dutch availability or taste classification is proposed.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p442301375"],"reference":"work:6288","checked_at":"2026-11-03T09:35:36.993Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-034.json","sources":["https://openlibrary.org/works/OL45104248W","https://data.bibliotheken.nl/id/nbt/p442301375"]},{"note":"Exact bound prior bulk-source attempt retained. No verified asset imported; existing shared resolver retained. Hosted exact-edition decoded front or documentedneutralplaceholder stillrequired.","type":"no_verified_cover_asset_retained","isbn13":"9789021488806","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":15206671,"receipt":"cover-archive-v2-readback.json","receiptSha256":"da70559e4d5f2dd3576e79714062a3263062ebe5401e0ef0ac880c708f94ec64"}],"checkedAt":"2026-11-03T09:35:37.000Z","editionKey":"/books/OL61514658M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL45104248W","reviewed_at":"2026-11-03T09:35:36.993+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_ty